static void *HmsDlopenMklRt(void)
{
  void       *handle;
  const char *root;
  char        path[4096];

  handle = dlopen("libmkl_rt.so", RTLD_LAZY | RTLD_GLOBAL);
  if (handle) return handle;
  (void)snprintf(hms_pardiso_lookup_error, sizeof(hms_pardiso_lookup_error), "dlopen libmkl_rt.so failed: %s", dlerror());
  root = getenv("MKLROOT");
  if (root && root[0]) {
    (void)snprintf(path, sizeof(path), "%s/lib/intel64/libmkl_rt.so", root);
    handle = dlopen(path, RTLD_LAZY | RTLD_GLOBAL);
    if (handle) return handle;
    (void)snprintf(hms_pardiso_lookup_error, sizeof(hms_pardiso_lookup_error), "dlopen %s failed: %s", path, dlerror());
  }
  handle = dlopen("/public4/soft/oneAPI/2022.1/mkl/latest/lib/intel64/libmkl_rt.so", RTLD_LAZY | RTLD_GLOBAL);
  if (handle) return handle;
  (void)snprintf(hms_pardiso_lookup_error, sizeof(hms_pardiso_lookup_error), "dlopen public oneAPI libmkl_rt.so failed: %s", dlerror());
  handle = dlopen("/APP/u22/x86/intel/oneapi2023.2/mkl/2023.2.0/lib/intel64/libmkl_rt.so", RTLD_LAZY | RTLD_GLOBAL);
  if (!handle) (void)snprintf(hms_pardiso_lookup_error, sizeof(hms_pardiso_lookup_error), "dlopen APP oneAPI libmkl_rt.so failed: %s", dlerror());
  return handle;
}

static void *HmsDlopenMklInterface(void)
{
  static void      *handle = NULL;
  static PetscBool  tried = PETSC_FALSE;
  static const char *names[] = {
    "libmkl_gf_lp64.so.2",
    "libmkl_gf_lp64.so",
    "libmkl_intel_lp64.so.2",
    "libmkl_intel_lp64.so"
  };

  if (tried) return handle;
  tried = PETSC_TRUE;
  for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
    handle = dlopen(names[i], RTLD_LAZY | RTLD_NOLOAD);
    if (handle) return handle;
  }
  return NULL;
}

static PardisoFunc GetPardisoFunc(void)
{
  static PardisoFunc fn = NULL;
  static PetscBool   tried = PETSC_FALSE;
  void              *handle;

  if (tried) return fn;
#if defined(_OPENMP)
#pragma omp critical(hms_pardiso_init)
#endif
  {
  if (!tried) {
  handle = dlopen(NULL, RTLD_LAZY);
  if (handle) {
    fn = (PardisoFunc)dlsym(handle, "pardiso");
    if (!fn) fn = (PardisoFunc)dlsym(handle, "pardiso_");
    if (!fn) fn = (PardisoFunc)dlsym(handle, "PARDISO");
  }
	  if (!fn) {
	    handle = HmsDlopenMklRt();
	    if (handle) {
	      fn = (PardisoFunc)dlsym(handle, "pardiso");
	      if (!fn) fn = (PardisoFunc)dlsym(handle, "pardiso_");
      if (!fn) fn = (PardisoFunc)dlsym(handle, "PARDISO");
      if (!fn) fn = (PardisoFunc)dlsym(handle, "PARDISO_");
      if (!fn) fn = (PardisoFunc)dlsym(handle, "pardiso__");
      if (!fn) fn = (PardisoFunc)dlsym(handle, "PARDISO__");
	    }
	  }
	  if (!fn && pardiso_) fn = (PardisoFunc)pardiso_;
	  if (!fn && !hms_pardiso_lookup_error[0]) (void)snprintf(hms_pardiso_lookup_error, sizeof(hms_pardiso_lookup_error), "libmkl_rt loaded but pardiso symbols were not found");
	  tried = PETSC_TRUE;
	  }
  }
  return fn;
}

static MklGetMaxThreadsFunc GetMklGetMaxThreadsFunc(void)
{
  static MklGetMaxThreadsFunc fn = NULL;
  static PetscBool            tried = PETSC_FALSE;
  void                       *handle;

  if (tried) return fn;
#if defined(_OPENMP)
#pragma omp critical(hms_mkl_thread_init)
#endif
  {
    if (!tried) {
      tried = PETSC_TRUE;
      handle = dlopen(NULL, RTLD_LAZY);
      if (handle) fn = (MklGetMaxThreadsFunc)dlsym(handle, "MKL_Get_Max_Threads");
      if (!fn) {
        handle = HmsDlopenMklInterface();
        if (handle) fn = (MklGetMaxThreadsFunc)dlsym(handle, "MKL_Get_Max_Threads");
      }
      if (!fn) {
        handle = HmsDlopenMklRt();
        if (handle) fn = (MklGetMaxThreadsFunc)dlsym(handle, "MKL_Get_Max_Threads");
      }
    }
  }
  return fn;
}

