static MklFreeBuffersFunc GetMklFreeBuffersFunc(const char name[])
{
  void *handle;

  handle = dlopen(NULL, RTLD_LAZY);
  if (handle) {
    MklFreeBuffersFunc fn = (MklFreeBuffersFunc)dlsym(handle, name);
    if (fn) return fn;
  }
  handle = HmsDlopenMklRt();
  return handle ? (MklFreeBuffersFunc)dlsym(handle, name) : NULL;
}

static int HmsMklGetCurrentThreads(void)
{
  MklGetMaxThreadsFunc get_threads = GetMklGetMaxThreadsFunc();
  return get_threads ? get_threads() : -1;
}

static void HmsMklSetThreadsIfAvailable(int threads)
{
  MklSetNumThreadsFunc set_threads;

  if (threads <= 0) return;
  set_threads = GetMklSetNumThreadsFunc();
  if (set_threads) set_threads(threads);
}

static void HmsMklFinalizeIfAvailable(void)
{
  MklFinalizeFunc finalize = GetMklFinalizeFunc();
  if (finalize) finalize();
}

static void HmsMklFreeBuffersIfAvailable(void)
{
  MklFreeBuffersFunc free_buffers = GetMklFreeBuffersFunc("mkl_free_buffers");
  MklFreeBuffersFunc thread_free_buffers = GetMklFreeBuffersFunc("mkl_thread_free_buffers");

  if (thread_free_buffers) thread_free_buffers();
  if (free_buffers) free_buffers();
}

static void HmsMallocTrimIfAvailable(void)
{
#if defined(__linux__)
  (void)malloc_trim(0);
#endif
}

static int HmsMklThreadLocalBegin(PetscBool enabled, int local_threads)
{
  MklSetNumThreadsLocalFunc set_local;

  if (!enabled || local_threads <= 0) return -1;
  set_local = GetMklSetNumThreadsLocalFunc();
  if (!set_local) return -1;
  return set_local(local_threads);
}

static void HmsMklThreadLocalEnd(int previous_threads)
{
  MklSetNumThreadsLocalFunc set_local;

  if (previous_threads < 0) return;
  set_local = GetMklSetNumThreadsLocalFunc();
  if (set_local) (void)set_local(previous_threads);
}

