static const char *MsGalerkinModeName(const MsCtx *ms)
{
  if (ms->ms_galerkin_sparse) return "petsc-sparse";
  if (ms->ms_galerkin_spmm) return "mkl-csr-spmm";
  return "element-blas";
}

