static inline PetscScalar MsCellPhiValue(const MsCtx *ms, const MsCellCache *cache, PetscInt lid, PetscInt q)
{
  if (cache->Phi) return cache->Phi[(size_t)lid * (size_t)ms->local_p_nodes + (size_t)q];
  return cache->PhiCol[(size_t)q * (size_t)ms->local_fine_nodes + (size_t)lid];
}

