typedef struct {
  PetscLogDouble phi_frob_sum, phi_max_sum, ac_frob_sum, shur_frob_sum;
  PetscLogDouble phi_frob_max, phi_max_max, ac_frob_max, shur_frob_max;
  PetscInt       phi_frob_cell, phi_max_cell, ac_frob_cell, shur_frob_cell;
  PetscInt       count;
} MsBasisScan;

static void MsBasisScanInit(MsBasisScan *scan)
{
  scan->phi_frob_sum = 0.0;
  scan->phi_max_sum = 0.0;
  scan->ac_frob_sum = 0.0;
  scan->shur_frob_sum = 0.0;
  scan->phi_frob_max = 0.0;
  scan->phi_max_max = 0.0;
  scan->ac_frob_max = 0.0;
  scan->shur_frob_max = 0.0;
  scan->phi_frob_cell = -1;
  scan->phi_max_cell = -1;
  scan->ac_frob_cell = -1;
  scan->shur_frob_cell = -1;
  scan->count = 0;
}

static void MsDecodeCellId(const MsCtx *ms, PetscInt cell, PetscInt *cy, PetscInt *cz, PetscInt *cx)
{
  *cx = cell % ms->coarse_x;
  cell /= ms->coarse_x;
  *cz = cell % ms->coarse_z;
  *cy = cell / ms->coarse_z;
}

static void MsBasisScanAdd(const MsCtx *ms, PetscInt cx, PetscInt cy, PetscInt cz, const PetscScalar Phi[], const PetscScalar Ac[], const PetscScalar S[], MsBasisScan *scan)
{
  PetscLogDouble phi2 = 0.0, phi_max = 0.0, ac2 = 0.0, s2 = 0.0;
  PetscLogDouble phi_frob, ac_frob, s_frob;
  PetscInt       cell = (cy * ms->coarse_z + cz) * ms->coarse_x + cx;

  for (PetscInt i = 0; i < ms->local_fine_nodes * ms->local_p_nodes; i++) {
    PetscReal a = PetscAbsScalar(Phi[i]);
    phi2 += (PetscLogDouble)a * (PetscLogDouble)a;
    if ((PetscLogDouble)a > phi_max) phi_max = (PetscLogDouble)a;
  }
  for (PetscInt i = 0; i < ms->local_p_nodes * ms->local_p_nodes; i++) {
    PetscReal a = PetscAbsScalar(Ac[i]);
    ac2 += (PetscLogDouble)a * (PetscLogDouble)a;
  }
  for (PetscInt i = 0; i < ms->local_p_bdry * ms->local_p_bdry; i++) {
    PetscReal a = PetscAbsScalar(S[i]);
    s2 += (PetscLogDouble)a * (PetscLogDouble)a;
  }
  phi_frob = PetscSqrtReal((PetscReal)phi2);
  ac_frob  = PetscSqrtReal((PetscReal)ac2);
  s_frob   = PetscSqrtReal((PetscReal)s2);

  scan->phi_frob_sum += phi_frob;
  scan->phi_max_sum += phi_max;
  scan->ac_frob_sum += ac_frob;
  scan->shur_frob_sum += s_frob;
  scan->count++;
  if (phi_frob > scan->phi_frob_max) {
    scan->phi_frob_max = phi_frob;
    scan->phi_frob_cell = cell;
  }
  if (phi_max > scan->phi_max_max) {
    scan->phi_max_max = phi_max;
    scan->phi_max_cell = cell;
  }
  if (ac_frob > scan->ac_frob_max) {
    scan->ac_frob_max = ac_frob;
    scan->ac_frob_cell = cell;
  }
  if (s_frob > scan->shur_frob_max) {
    scan->shur_frob_max = s_frob;
    scan->shur_frob_cell = cell;
  }
}

static PetscErrorCode MsBasisScanReport(const MsCtx *ms, const MsBasisScan *local)
{
  PetscLogDouble sums[4], gsums[4];
  PetscInt       counts[1], gcounts[1];
  struct {
    double val;
    int    loc;
  } in[4], out[4];

  PetscFunctionBeginUser;
  sums[0] = local->phi_frob_sum;
  sums[1] = local->phi_max_sum;
  sums[2] = local->ac_frob_sum;
  sums[3] = local->shur_frob_sum;
  counts[0] = local->count;
  PetscCallMPI(MPI_Reduce(sums, gsums, 4, MPI_DOUBLE, MPI_SUM, 0, PETSC_COMM_WORLD));
  PetscCallMPI(MPI_Reduce(counts, gcounts, 1, MPIU_INT, MPI_SUM, 0, PETSC_COMM_WORLD));

  in[0].val = (double)local->phi_frob_max; in[0].loc = (int)local->phi_frob_cell;
  in[1].val = (double)local->phi_max_max;  in[1].loc = (int)local->phi_max_cell;
  in[2].val = (double)local->ac_frob_max;  in[2].loc = (int)local->ac_frob_cell;
  in[3].val = (double)local->shur_frob_max; in[3].loc = (int)local->shur_frob_cell;
  PetscCallMPI(MPI_Reduce(in, out, 4, MPI_DOUBLE_INT, MPI_MAXLOC, 0, PETSC_COMM_WORLD));

  {
    PetscMPIInt rank;
    PetscCallMPI(MPI_Comm_rank(PETSC_COMM_WORLD, &rank));
    if (!rank) {
    PetscInt cy, cz, cx;
    PetscReal inv = gcounts[0] > 0 ? 1.0 / (PetscReal)gcounts[0] : 0.0;
    PetscCall(PetscPrintf(PETSC_COMM_SELF, "HMS basis all-cell scan: cells %" PetscInt_FMT ", diagnostics are source-independent local-operator quantities\n", gcounts[0]));
    MsDecodeCellId(ms, (PetscInt)out[0].loc, &cy, &cz, &cx);
    PetscCall(PetscPrintf(PETSC_COMM_SELF, "  ||Phi||_F      avg %.6e max %.6e at cell y/z/x %" PetscInt_FMT "/%" PetscInt_FMT "/%" PetscInt_FMT " max/avg %.3f\n", (double)(gsums[0] * inv), out[0].val, cy, cz, cx, (double)(out[0].val / PetscMax((PetscReal)(gsums[0] * inv), PETSC_SMALL))));
    MsDecodeCellId(ms, (PetscInt)out[1].loc, &cy, &cz, &cx);
    PetscCall(PetscPrintf(PETSC_COMM_SELF, "  max|Phi|       avg %.6e max %.6e at cell y/z/x %" PetscInt_FMT "/%" PetscInt_FMT "/%" PetscInt_FMT " max/avg %.3f\n", (double)(gsums[1] * inv), out[1].val, cy, cz, cx, (double)(out[1].val / PetscMax((PetscReal)(gsums[1] * inv), PETSC_SMALL))));
    MsDecodeCellId(ms, (PetscInt)out[2].loc, &cy, &cz, &cx);
    PetscCall(PetscPrintf(PETSC_COMM_SELF, "  ||Ac||_F       avg %.6e max %.6e at cell y/z/x %" PetscInt_FMT "/%" PetscInt_FMT "/%" PetscInt_FMT " max/avg %.3f\n", (double)(gsums[2] * inv), out[2].val, cy, cz, cx, (double)(out[2].val / PetscMax((PetscReal)(gsums[2] * inv), PETSC_SMALL))));
    MsDecodeCellId(ms, (PetscInt)out[3].loc, &cy, &cz, &cx);
    PetscCall(PetscPrintf(PETSC_COMM_SELF, "  ||S_loc||_F    avg %.6e max %.6e at cell y/z/x %" PetscInt_FMT "/%" PetscInt_FMT "/%" PetscInt_FMT " max/avg %.3f\n", (double)(gsums[3] * inv), out[3].val, cy, cz, cx, (double)(out[3].val / PetscMax((PetscReal)(gsums[3] * inv), PETSC_SMALL))));
    }
  }
  PetscFunctionReturn(PETSC_SUCCESS);
}

