static inline PetscInt NodeId(const AppCtx *ctx, PetscInt ix, PetscInt iy, PetscInt iz)
{
  return (iy * (ctx->ne_z + 1) + iz) * (ctx->ne_x + 1) + ix;
}

static inline PetscInt GridNodeId(PetscInt ne_x, PetscInt ne_y, PetscInt ne_z, PetscInt ix, PetscInt iy, PetscInt iz)
{
  return (iy * (ne_z + 1) + iz) * (ne_x + 1) + ix;
}

